def _fixture(shape, case_index):
    assert shape["containsText"] is False
    lengths, rows = shape["evidenceIdentityLengths"], shape["evidenceShape"]
    ids = [str(i + 1).zfill(pair[0]) for i, pair in enumerate(lengths)]
    assert len(set(ids)) == len(ids)
    files, catalog = {}, []
    for i, (file_ordinal, category, start, end, citable) in enumerate(rows):
        size = lengths[i][1]
        fid = "f" + str(file_ordinal).zfill(size - 1)
        assert len(fid) == size
        assert files.setdefault(file_ordinal, fid) == fid
        catalog.append({"evidenceId": ids[i], "fileId": fid, "materialCategory": category,
                        "sourceStart": start, "sourceEnd": end, "citable": citable})
    scopes = [{"topic": topic, "responsibleParty": party,
               "trigger": None if count is None else chr(0x4E00 + i) * count}
              for i, (topic, party, count) in enumerate(shape["scopes"])]
    # The original registry deduplicates exact full scopes. Preserve that
    # equivalence relation even for different triggers of the same length.
    assert len({json.dumps(scope, sort_keys=True) for scope in scopes}) == len(scopes)
    analyses = []
    for ai, original in enumerate(shape["analyses"]):
        hints = []
        for category, attention, kind, si, problem, comparison, title_chars, description_chars in original["hints"]:
            hints.append({"category": category, "attention": attention, "claimKind": kind,
                "obligationScope": scopes[si], "title": "题" * title_chars, "description": "述" * description_chars,
                "problemEvidenceIds": [ids[i] for i in problem],
                "comparisonEvidenceIds": [ids[i] for i in comparison], "unavailableMaterialCategory": None})
        analyses.append({"logicalKey": hashlib.sha256(f"public-shape-{case_index}-{ai}".encode()).hexdigest(),
            "checkpointHash": hashlib.sha256(f"public-packet-{case_index}-{ai}".encode()).hexdigest(),
            "summary": "概" * original["summaryChars"], "hints": hints})
    states = [{"fileId": files[i], "category": category, "state": state}
              for i, category, state in shape["materialStates"]]
    return analyses, catalog, states


@pytest.mark.parametrize("case_index,analysis_count,leaf_count,scope_count,evidence_count", [
    (0, 16, 53, 44, 528), (1, 7, 58, 46, 121),
])
def test_real_frozen_metadata_topology_and_full_all_keep_capacity(case_index, analysis_count, leaf_count, scope_count, evidence_count):
    shape = _SAFE_SHAPES[case_index]
    analyses, catalog, states = _fixture(shape, case_index)
    before = copy.deepcopy(analyses)
    bundle = build_hierarchy_inputs(analyses, catalog, material_states=states)
    assert len(analyses) == analysis_count and len(bundle["leaves"]) == leaf_count
    assert len(bundle["scopes"]) == scope_count and len(catalog) == evidence_count
    assert analyses == before
    assert sorted(i for g in bundle["groups"] for i in g["members"]) == list(range(analysis_count))
    digests, consumed = [], []
    for group in bundle["groups"]:
        hints, lineage = [], []
        for lid in group["leafIds"]:
            hint = copy.deepcopy(bundle["leaves"][lid]["hint"])
            hints.append(hint)
            basis = list(dict.fromkeys(hint["problemEvidenceIds"] + hint["comparisonEvidenceIds"]))
            lineage.append([lid, "KEEP", len(hints) - 1, basis, "KEEP"])
            consumed.append(lid)
        witness = {"summary": "容量测试：逐项保留原意见",
            "scopeStatus": "CHECKED_WITH_FINDINGS" if hints else "CHECKED_NO_RELEVANT_FINDINGS",
            "hints": hints, "lineage": lineage}
        validated = validate_group_lineage(witness, group, bundle)
        digest = group_digest(validated, group, bundle)
        assert len(group["source"]) <= 12000
        digests.append(digest)
    assert len(consumed) == leaf_count and set(consumed) == set(bundle["leaves"])
    source = final_source(bundle, digests)
    assert len(source) <= 12000
    assert bundle["finalFixedChars"] + sum(g["digestMaxChars"] for g in bundle["groups"]) == 12000
    # Exact ranges, evidence-list order and every original directional ref are
    # still in the private fixture/proof, despite FINAL's smaller model view.
    assert [(e["sourceStart"], e["sourceEnd"], e["citable"]) for e in catalog] == [
        (row[2], row[3], row[4]) for row in shape["evidenceShape"]]
